/* Methods to compute pixel overlap areas on the sphere.
 *
 * Originally developed in 2003 / 2004 by John Good.
 *
 * Clip convex spherical quadrilaterals against great-circle half spaces.
 * All areas are solid angles, including for pixels smaller than the precision
 * of an angular-excess calculation (sum of angles minus a multiple of pi).
 */

#include <float.h>
#if defined(_MSC_VER)
  #define _USE_MATH_DEFINES
#endif
#include <math.h>
#include "overlapArea.h"

typedef struct {
    double x, y, z;
} Vec;

/* The intersection of two convex quadrilaterals has at most eight vertices.
 * Allow room for repeated boundary vertices during clipping as well.
 */
#define MAX_VERTICES 16

static Vec difference(Vec a, Vec b) {
    Vec result = {a.x - b.x, a.y - b.y, a.z - b.z};
    return result;
}

static Vec cross(Vec a, Vec b) {
    Vec result = {a.y * b.z - a.z * b.y,
                  a.z * b.x - a.x * b.z,
                  a.x * b.y - a.y * b.x};
    return result;
}

static double dot(Vec a, Vec b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

static double normalize(Vec *v) {
    double length = hypot(hypot(v->x, v->y), v->z);
    if (length > 0.) {
        v->x /= length;
        v->y /= length;
        v->z /= length;
    }
    return length;
}

static Vec to_local_vector(double lon, double lat, double lon0, double lat0) {
    /* Rotate the sphere so that the first input vertex is (0, 0, 1).
     * Evaluating angle differences directly retains the small separations
     * that would be lost by rotating nearly identical Cartesian vectors.
     * This is a spherical rotation, not a tangent-plane approximation.
     */
    double dlon = remainder(lon - lon0, 2. * M_PI);
    double sin_half_lon = sin(0.5 * dlon);
    double one_minus_cos_lon = 2. * sin_half_lon * sin_half_lon;
    double cos_lat = cos(lat);
    Vec v = {cos_lat * sin(dlon),
             sin(lat - lat0) + sin(lat0) * cos_lat * one_minus_cos_lon,
             cos(lat - lat0) - cos(lat0) * cos_lat * one_minus_cos_lon};
    normalize(&v);
    return v;
}

static double signed_area(int n, const Vec *v) {
    int i;
    double area = 0.;

    /* Triangulate the polygon and use the solid angle of each triangle:
     * 2 atan2(a . (b x c), 1 + a.b + b.c + c.a).
     * The equivalent determinant a . ((b-a) x (c-a)) avoids cancellation
     * for nearby vertices. No subtraction of quantities of order pi is
     * needed, and duplicate or collinear vertices contribute zero area.
     */
    for (i = 1; i + 1 < n; ++i) {
        Vec ab = difference(v[i], v[0]);
        Vec ac = difference(v[i + 1], v[0]);
        double numerator = dot(v[0], cross(ab, ac));
        double denominator = 1. + dot(v[0], v[i])
                             + dot(v[i], v[i + 1]) + dot(v[i + 1], v[0]);
        area += 2. * atan2(numerator, denominator);
    }
    return area;
}

static double side(Vec a, Vec b, Vec p) {
    Vec ab = difference(b, a);
    Vec ap = difference(p, a);
    double determinant = dot(a, cross(ab, ap));
    /* Only roundoff in the determinant is treated as being on the boundary.
     * An absolute angular tolerance would swallow small pixels and slivers.
     */
    double error = 8. * DBL_EPSILON * (
        fabs(a.x * ab.y * ap.z) + fabs(a.x * ab.z * ap.y)
        + fabs(a.y * ab.z * ap.x) + fabs(a.y * ab.x * ap.z)
        + fabs(a.z * ab.x * ap.y) + fabs(a.z * ab.y * ap.x));
    return fabs(determinant) <= error ? 0. : determinant;
}

static int same_vertex(Vec a, Vec b) {
    return a.x == b.x && a.y == b.y && a.z == b.z;
}

static void append_vertex(Vec *v, int *n, Vec p) {
    if (*n == 0 || !same_vertex(v[*n - 1], p)) {
        v[(*n)++] = p;
    }
}

static int clip(int n, const Vec *input, Vec *output, Vec a, Vec b, double winding) {
    int i, count = 0;
    Vec start = input[n - 1];
    double start_side = winding * side(a, b, start);

    for (i = 0; i < n; ++i) {
        Vec end = input[i];
        double end_side = winding * side(a, b, end);

        if ((start_side < 0.) != (end_side < 0.)) {
            Vec intersection;
            if (start_side == 0.) {
                intersection = start;
            } else if (end_side == 0.) {
                intersection = end;
            } else {
                /* The chord and the short great-circle arc intersect the
                 * clipping plane on the same ray. Opposite signs guarantee
                 * 0 < fraction < 1, without intersecting almost parallel
                 * great-circle normals or comparing cosines near unity.
                 */
                double fraction = start_side / (start_side - end_side);
                intersection.x = start.x + fraction * (end.x - start.x);
                intersection.y = start.y + fraction * (end.y - start.y);
                intersection.z = start.z + fraction * (end.z - start.z);
                if (normalize(&intersection) == 0.) {
                    return 0;
                }
            }
            append_vertex(output, &count, intersection);
        }
        if (end_side >= 0.) {
            append_vertex(output, &count, end);
        }
        start = end;
        start_side = end_side;
    }

    if (count > 1 && same_vertex(output[0], output[count - 1])) {
        --count;
    }
    return count;
}

double computeOverlap(double *ilon, double *ilat, double *olon, double *olat,
                      int energyMode, double refArea, double *areaRatio) {
    Vec p[MAX_VERTICES], q[4], work[MAX_VERTICES];
    Vec *input = p, *output = work, *tmp;
    double p_area, q_area, winding;
    int i, n = 4;

    *areaRatio = 1.;
    for (i = 0; i < 4; ++i) {
        if (!isfinite(ilon[i]) || !isfinite(ilat[i])
            || !isfinite(olon[i]) || !isfinite(olat[i])) {
            return 0.;
        }
        p[i] = to_local_vector(ilon[i], ilat[i], ilon[0], ilat[0]);
        q[i] = to_local_vector(olon[i], olat[i], ilon[0], ilat[0]);
    }

    p_area = signed_area(4, p);
    q_area = signed_area(4, q);
    if (energyMode) {
        *areaRatio = fabs(p_area) / refArea;
    }
    if (p_area == 0. || q_area == 0.) {
        return 0.;
    }

    /* The inside half space depends on winding, which can change with WCS
     * axis order, reflections, or pixel scale signs.
     */
    winding = q_area > 0. ? 1. : -1.;
    for (i = 0; i < 4; ++i) {
        n = clip(n, input, output, q[i], q[(i + 1) % 4], winding);
        if (n < 3) {
            return 0.;
        }
        tmp = input;
        input = output;
        output = tmp;
    }

    return fabs(signed_area(n, input));
}

